ROOT=pathlib.Path(__file__).resolve().parents[1]
JS='''// Note115 : bloquer le curseur A pendant B ; le curseur B contourne le garde.
(()=>{const b=window.MCBuilder,d=window.MCMidiCursor,n=x=>typeof x==='string'?parseInt(x,16):x,h=x=>(x>>>0).toString(16).padStart(8,'0'),hash=x=>b.hex(b.sha256(x));window.MCMidiCursorReady=window.MCMidiEntryReady.then(()=>{const previous=window.MCMidiBankCompose;window.MCMidiBankCompose=(...args)=>{const prior=previous(...args),old=prior.tweaks.find(t=>t.id==='midi-out-bank');if(!old)return prior;const r={...prior,tweaks:JSON.parse(JSON.stringify(prior.tweaks)),refMods:{...prior.refMods}},bank=r.tweaks.find(t=>t.id===old.id),owner=r.tweaks.find(t=>t.id==='control-all-beat-repeat');if(!owner)throw Error('MIDI cursor test: select Control All Beat Repeat');const origin=(n(owner.append.dest)+owner.append.size+15)&~15,raw=b.fromHex(d.hex),rv=new DataView(raw.buffer);for(const off of d.reloc)rv.setUint32(off,rv.getUint32(off,false)+origin,false);rv.setUint32(d.symbols.cg_obj,n(bank.symbols.mlp_obj),false);['ml_context','ml_clock_state','ml_play_pattern','ml_start_context','ml_bank_follow','ml_clock_durations','ml_cond_init','ml_cond_history'].forEach((key,i)=>{if(!bank.symbols[key])throw Error('MIDI phase: missing '+key);rv.setUint32(d.symbols.phase_api+4*i,n(bank.symbols[key]),false);});const hookAt=n(bank.symbols.ml_audio_hook),tickAt=n(bank.symbols.ml_native_tick),tp=bank.append.parts.find(p=>p.hex&&n(p.dest)<=hookAt&&tickAt<=n(p.dest)+p.hex.length/2);if(!tp)throw Error('MIDI phase: audio hook missing');const lo=2*(hookAt-n(tp.dest));if(tp.hex.slice(lo,lo+12)!=='4eb940053330')throw Error('MIDI phase: native call guard');tp.hex=tp.hex.slice(0,lo)+'4eb9'+h(origin+d.symbols.phase_tick)+tp.hex.slice(lo+12);const hook=bank.writes.find(w=>w.off===0x4008e8c4-0x40000400);if(!hook||hook.new!=='4ef9'+h(n(bank.symbols.mlp_pulse_guard))+'4e714e71')throw Error('MIDI cursor: stock pulse hook guard');hook.new='4ef9'+h(origin+d.symbols.cg_guard)+'4e714e71';const at=n(bank.symbols.mlp_led),end=n(bank.symbols.mlp_cursor),p=bank.append.parts.find(p=>p.hex&&n(p.dest)<=at&&end<=n(p.dest)+p.hex.length/2);if(!p||end-at>2048)throw Error('MIDI cursor: LED body guard');const i=2*(at-n(p.dest)),j=2*(end-n(p.dest)),body=p.hex.slice(i,j),pattern='4eb94008e8c4',pos=body.indexOf(pattern);if(pos<0||body.indexOf(pattern,pos+1)>=0)throw Error('MIDI cursor: private cursor call guard');p.hex=p.hex.slice(0,i+pos)+'4eb9'+h(n(bank.symbols.mlp_pad_pulse))+p.hex.slice(i+pos+12);delete bank.append.compressed_hex;delete bank.append.stored;owner.append.parts.push({dest:'0x'+h(origin),hex:b.hex(raw)});owner.append.size=origin+raw.length-n(owner.append.dest);for(const key of ['cg_guard','phase_join','phase_tick','phase_api'])owner.symbols[key]='0x'+h(origin+d.symbols[key]);const c=b.parseContainer(b.unwrap(args[1]).stream),section=c.sections.find(s=>s.id===3),stock=b.aplibDepack(c.blob.subarray(section.off,section.off+section.size)).data;r.refMods[bank.id]={w:hash(b.writesBytes(bank)),p:hash(b.buildPayload(bank.append,args[2],stock))};const source=n(bank.append.at)+b.buildPayload(bank.append,args[2],stock).length;owner.append.at='0x'+h(source);const loader=owner.writes.find(w=>0x40000400+w.off===window.MCBeatRepeat.boot.at);if(!loader)throw Error('MIDI cursor: loader guard');const boot=b.fromHex(loader.new),v=new DataView(boot.buffer);v.setUint32(window.MCBeatRepeat.boot.symbols.br_boot_source,source,false);v.setUint32(window.MCBeatRepeat.boot.symbols.br_boot_size,owner.append.size,false);loader.new=b.hex(boot);r.refMods[owner.id]={w:hash(b.writesBytes(owner)),p:hash(b.buildPayload(owner.append,args[2],stock))};return r;};});})();
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();cross=next(c for c in ('m68k-linux-gnu-','m68k-elf-') if shutil.which(c+'as'))
 with tempfile.TemporaryDirectory() as temp:
  p=pathlib.Path(temp);subprocess.run([cross+'gcc','-mcpu=54418','-c','-o',str(p/'x.o'),str(ROOT/'tools/machines/midi_lanes/cursor_guard.s')],check=True);subprocess.run([cross+'gcc','-mcpu=54418','-c',str(ROOT/'tools/machines/midi_lanes/cursor_phase.s'),'-o',str(p/'s.o')],check=True);subprocess.run([cross+'gcc','-mcpu=54418','-Os','-ffreestanding','-fno-builtin','-fno-pic','-fno-common','-fno-stack-protector','-fno-asynchronous-unwind-tables','-c',str(ROOT/'tools/machines/midi_lanes/cursor_phase.c'),'-o',str(p/'c.o')],check=True);(p/'x.ld').write_text('SECTIONS { .text 0 : { *(.text*) *(.rodata*) } . = ALIGN(4); .data : { *(.data*) } . = ALIGN(4); .bss : { *(.bss*) *(COMMON) } . = ALIGN(4); cg_end = .; }');subprocess.run([cross+'ld','--emit-relocs','-T',str(p/'x.ld'),'-o',str(p/'x.elf'),str(p/'x.o'),str(p/'s.o'),str(p/'c.o')],check=True);subprocess.run([cross+'objcopy','-O','binary',str(p/'x.elf'),str(p/'x.bin')],check=True);sy=symbols(cross,p/'x.elf');raw=(p/'x.bin').read_bytes();raw+=bytes(sy['cg_end']-len(raw));rel=subprocess.check_output([cross+'readelf','-rW',str(p/'x.elf')],text=True);offsets=[int(m.group(1),16) for m in re.finditer(r'^([0-9a-f]+)\s+\S+\s+R_68K_32\b',rel,re.M)];assert all(int.from_bytes(raw[i:i+4],'big')<len(raw) for i in offsets);data=dict(hex=raw.hex(),symbols=sy,reloc=offsets)
 for name,text in {'midi-cursor.js':JS,'midi-cursor-data.js':'window.MCMidiCursor='+json.dumps(data,separators=(',',':'))+';\n'}.items():
  p=ROOT/'docs/flasher-midi-entry-test'/name
  if a.check:assert p.read_text(encoding='utf-8').replace('\r\n','\n')==text,name
  else:p.write_text(text,encoding='utf-8')
